"""Small dictionary-based internationalisation helpers for the GUI."""

current_language = "es"


def set_language(lang: str):
    """Select the active GUI language."""
    global current_language
    current_language = lang if lang in TRANSLATIONS else "en"


def _(key: str) -> str:
    """Return the translated text for *key*, falling back to English and then key."""
    return TRANSLATIONS.get(current_language, {}).get(
        key, TRANSLATIONS["en"].get(key, key)
    )


